def multi_head_attention(Q, K, V, h=8, d_model=512, mask=None):
    d_k = d_v = d_model // h         # 512 / 8 = 64
    heads = []
    for i in range(h):
        q_i = Q @ W_Q[i]             # (d_model, d_k)
        k_i = K @ W_K[i]             # (d_model, d_k)
        v_i = V @ W_V[i]             # (d_model, d_v)
        heads.append(scaled_dot_product_attention(q_i, k_i, v_i, mask))
    return concat(heads, axis=-1) @ W_O   # (h * d_v, d_model)

